/// <summary>
/// designed from AVA
/// </summary>
[ExtensionOf(classStr(AVAItemSetLineValidation))]
internal final class AVAAVAItemSetLineValidation_Extension
{
}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_salesParmUpdate">_salesParmUpdate</param>
/// <returns>hasNotDeliveredParmLine</returns>
public static boolean hasNotDeliveredParmLine(SalesParmUpdate   _salesParmUpdate)
{
    boolean  ret = next hasNotDeliveredParmLine(_salesParmUpdate);
    SalesParmLine       salesParmLine;
    SalesLine           checkSalesLine;
    SalesTable          salesTable;
    SalesOrigin         salesOrigin;

    select firstonly  ParmId, DeliverNow, RecId from  salesParmLine
            where salesParmLine.ParmId == _salesParmUpdate.ParmId
               && salesParmLine.DeliverNow != 0
                    join RecId, AVAItemSetComponent, SalesId from  checkSalesLine
                        where checkSalesLine.RecId == salesParmLine.SalesLineRecId
                           && checkSalesLine.AVAItemSetComponent == NoYes::Yes
                    join SalesId, SalesType from salesTable
                        where salesTable.SalesId == checkSalesLine.SalesId
                           && salesTable.SalesType == SalesType::Sales
                                notexists join salesOrigin
                                    where salesOrigin.OriginId == SalesTable.SalesOriginId
                                       && SalesOrigin.AVACommercialAgentOrig == NoYes::Yes;

    if (salesParmLine.RecId)
    {
        ret = true;
    }
    else
    {
        ret = false;
    }

    return ret;
}
